// Polling every 1-2 seconds
useQuery({ queryKey: ['time'], refetchInterval: 1000 })
useQuery({ queryKey: ['simulation-status'], refetchInterval: 2000 })

// Subscribe once, receive pushes
ws.onmessage = (event) => {
  const { type, data } = JSON.parse(event.data)
  if (type === 'time_updated') updateTimeDisplay(data)
  if (type === 'event_executed') invalidateQueries(['events'])
}
